<template>
  <main class="app-container pc-page">
    <h1>后台任务</h1><p class="pc-muted">Web、CLI、Runtime 和微信共用中心任务。租约失效须核对未知副作用，不能盲目重跑。</p>
    <el-alert v-if="pageError || workspaceError || error" :title="pageError || workspaceError || error" type="error" :closable="false" />
    <div class="pc-toolbar"><label for="pc-task-workspace">工作区</label><el-select id="pc-task-workspace" v-model="workspaceId"><el-option v-for="workspace in workspaces" :key="workspace.id" :label="workspace.name" :value="workspace.id" /></el-select></div><el-tabs v-model="taskTab"><el-tab-pane v-if="checkPermi(['paicli:task:read'])" label="本人后台任务" name="tasks" /><el-tab-pane v-if="checkPermi(['paicli:approval:decide'])" label="工作区待批准" name="approvals" /></el-tabs><PendingApprovals v-if="taskTab === 'approvals'" :workspace-id="workspaceId" /><section v-if="taskTab === 'tasks' && checkPermi(['paicli:task:read'])"><el-form inline @submit.prevent="query"><el-form-item label="任务状态"><el-select v-model="filter.status" clearable style="width:200px"><el-option v-for="state in states" :key="state" :label="stateName(state)" :value="state" /></el-select></el-form-item><el-form-item label="发起人"><el-input v-model="filter.requester" placeholder="用户名" clearable /></el-form-item><el-form-item label="任务内容"><el-input v-model="filter.search" clearable /></el-form-item><el-form-item><el-button type="primary" native-type="submit" :loading="loading">查询</el-button><el-button v-hasPermi="['paicli:task:write']" :disabled="!workspaceId" @click="createOpen = true">创建后台任务</el-button></el-form-item></el-form>
    <el-table v-loading="loading" :data="tasks"><el-table-column prop="title" label="任务" min-width="180" /><el-table-column label="来源 / 模式" min-width="150"><template #default="{ row }">{{ row.source }} / {{ modeName(row.mode) }}</template></el-table-column><el-table-column label="状态" min-width="170"><template #default="{ row }"><el-tag>{{ stateName(row.status) }}</el-tag><p v-if="row.failureReason" class="pc-muted">{{ row.failureReason }}</p></template></el-table-column><el-table-column label="进度" width="130"><template #default="{ row }"><el-progress v-if="row.progress !== undefined" :percentage="row.progress" /><span v-else>等待上报</span></template></el-table-column><el-table-column prop="requesterName" label="发起人" width="100" /><el-table-column label="时间" min-width="180"><template #default="{ row }">{{ displayTime(row.updatedAt) }}</template></el-table-column><el-table-column label="用量" width="150"><template #default="{ row }">{{ row.usage?.totalTokens ?? '待上报' }} Token</template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="showTask(row.id)">详情与日志</el-button><el-button v-hasPermi="['paicli:task:cancel']" link type="danger" :disabled="!!row.importBatchId || !canCancel(row.status) || busy" @click="cancel(row)">取消</el-button></template></el-table-column></el-table>
    <el-empty v-if="!loading && !tasks.length" description="当前筛选没有任务" /><Pagination v-if="total > 0" v-model:page="filter.pageNum" v-model:limit="filter.pageSize" :total="total" @pagination="loadTasks" /></section>
    <el-dialog v-model="createOpen" title="创建后台编码任务" width="650px" class="pc-dialog"><el-form label-width="100px"><el-form-item label="标题"><el-input v-model="form.title" maxlength="120" /></el-form-item><el-form-item label="Runner"><el-select v-model="form.runnerId" class="pc-wide"><el-option v-for="runner in runners" :key="runner.id" :value="runner.id" :label="`${runner.name} · ${stateName(runner.status)}`" :disabled="runner.status !== 'ONLINE'" /></el-select></el-form-item><el-form-item label="模型"><el-select v-model="form.modelId" class="pc-wide" filterable><el-option v-for="model in models" :key="model.id" :value="model.id" :label="model.modelId" :disabled="!model.enabled" /></el-select></el-form-item><el-form-item label="模式"><el-select v-model="form.mode"><el-option label="直接执行" value="REACT" /><el-option label="计划执行" value="PLAN" /><el-option label="团队协作" value="TEAM" /></el-select></el-form-item><el-form-item label="任务与验收"><el-input v-model="form.text" type="textarea" :rows="6" placeholder="写清目标、范围和可观察的正确结果" /></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false" /><template #footer><el-button @click="createOpen = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!form.title.trim() || !form.text.trim() || !form.runnerId || !form.modelId" @click="create">提交后台任务</el-button></template></el-dialog>
    <el-drawer v-model="detailOpen" title="任务详情、工具证据与恢复" size="850px"><el-button :loading="detailLoading" @click="selected && showTask(selected.id)">刷新真实状态</el-button><template v-if="selected"><p><strong>{{ selected.title }}</strong> · {{ stateName(selected.status) }}</p><pre class="pc-pre">{{ safeText(selected.input) }}</pre><el-descriptions :column="1" border><el-descriptions-item label="尝试 / 隔离令牌">{{ selected.attemptId }} / {{ selected.fencingToken }}</el-descriptions-item><el-descriptions-item label="租约有效期">{{ displayTime(selected.leaseExpiresAt) }}</el-descriptions-item><el-descriptions-item label="已确认事件">{{ selected.lastConfirmedSequence ?? '无' }}</el-descriptions-item></el-descriptions><el-alert v-if="selected.status === 'CANCELLING'" title="正在停止工具进程树。最终回执前不能宣称已取消，已发生结果仍需核对。" type="warning" :closable="false" />
      <el-tabs><el-tab-pane label="工具与事件"><el-collapse><el-collapse-item v-for="tool in selected.tools" :key="tool.id" :title="`${tool.toolName} · ${stateName(tool.status)}`"><pre class="pc-pre">{{ safeText(tool.arguments) }}</pre><pre v-if="tool.result || tool.error" class="pc-pre">{{ safeText(tool.result || tool.error) }}</pre><ArtifactEvidence :result="tool.result" :artifact-id="tool.artifactId" :session-id="selected.sessionId" /><el-button v-if="tool.approvalId" v-hasPermi="['paicli:approval:decide']" @click="openApproval(tool.approvalId)">查看批准影响</el-button></el-collapse-item></el-collapse><TaskEvents :task="selected" /><el-button v-for="artifact in selected.artifacts" :key="artifact.id" v-hasPermi="['paicli:artifact:read']" @click="download(artifact.id, artifact.fileName)">下载 {{ artifact.fileName }}</el-button></el-tab-pane><el-tab-pane label="计划与团队"><PlanPanel :plan="selected.plan" :readonly="!!selected.importBatchId" :active="!['COMPLETED','FAILED','CANCELLED','RECONCILE_REQUIRED'].includes(selected.status)" @refresh="showTask(selected.id)" @cancel="cancel(selected)" /></el-tab-pane><el-tab-pane label="人工批准"><div v-for="approval in selected.approvals" :key="approval.id"><p>{{ approval.toolName }} · {{ stateName(approval.status) }}</p><el-button v-hasPermi="['paicli:approval:decide']" @click="openApproval(approval.id)">查看完整申请</el-button></div><el-empty v-if="!selected.approvals.length" description="没有审批申请" /></el-tab-pane><el-tab-pane label="恢复核对"><el-alert v-if="selected.status !== 'RECONCILE_REQUIRED'" title="该任务当前不需要人工恢复核对。" type="info" :closable="false" /><template v-else-if="selected.recovery"><el-alert title="上次执行结果未知，禁止直接重新运行。先核对最后回执、当前文件和未知外部影响。" type="warning" :closable="false" /><h3>最后工具结果</h3><pre class="pc-pre">{{ safeText(selected.recovery.lastToolResult) }}</pre><h3>当前文件差异</h3><pre class="pc-pre">{{ safeText(selected.recovery.fileDiff) }}</pre><ul><li v-for="effect in selected.recovery.unknownEffects" :key="effect">{{ safeText(effect) }}</li></ul><label class="pc-label">核对结论</label><el-select v-model="recoveryDecision"><el-option v-for="decision in selected.recovery.allowedDecisions" :key="decision" :value="decision" :label="recoveryLabels[decision] || decision" /></el-select><label class="pc-label" for="pc-recovery-fingerprint">当前工作区 SHA-256 指纹</label><el-input id="pc-recovery-fingerprint" v-model="recoveryFingerprint" placeholder="由目标 Runner 核对当前文件后提供，不能沿用登记指纹" /><label class="pc-label" for="pc-recovery-evidence">实际证据与核对说明</label><el-input id="pc-recovery-evidence" v-model="recoveryEvidence" type="textarea" :rows="4" /><el-button v-hasPermi="['paicli:task:recover']" type="primary" :disabled="!recoveryDecision || !recoveryEvidence.trim() || !/^[a-f0-9]{64}$/i.test(recoveryFingerprint)" :loading="busy" @click="reconcile">提交核对结果</el-button></template><el-alert v-else title="恢复证据尚未上报，当前不能判定或重新执行。" type="warning" :closable="false" /></el-tab-pane></el-tabs></template></el-drawer>
    <ApprovalDrawer v-model="approvalOpen" :approval="selected?.approvals.find(item => item.id === approvalId)" @decided="selected && showTask(selected.id)" />
  </main>
</template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute } from 'vue-router'
import Pagination from '@/components/Pagination/index.vue'
import { checkPermi } from '@/utils/permission'
import { cancelTask, createTask, getTask, listTasks, reconcileTask } from '@/api/paicli/tasks'
import { listRunners } from '@/api/paicli/workspaces'
import { listModels } from '@/api/paicli/connections'
import { downloadArtifact } from '@/api/paicli/sessions'
import type { PcMode, PcModel, PcRunner, PcTask, PcTaskDetail } from '@/types/paicli'
import ApprovalDrawer from '../components/ApprovalDrawer.vue'
import PendingApprovals from '../components/PendingApprovals.vue'
import PlanPanel from '../components/PlanPanel.vue'
import ArtifactEvidence from '../components/ArtifactEvidence.vue'
import TaskEvents from '../components/TaskEvents.vue'
import { useOperations } from '../useOperations'
import { useWorkspace } from '../useWorkspace'
import { canCancel, displayTime, errorText, modeName, operationKeys, safeText, saveDownload, stateName } from '../model'
import '../page.css'
defineOptions({ name: 'PaicliTasks' })
const route = useRoute()
const { workspaces, workspaceId, workspaceError, loadWorkspaces } = useWorkspace(), { busy, error, run } = useOperations(), keys = operationKeys()
const taskTab=ref(checkPermi(['paicli:task:read'])?'tasks':'approvals')
const tasks = ref<PcTask[]>([]), total = ref(0), loading = ref(false), pageError = ref(''), runners = ref<PcRunner[]>([]), models = ref<PcModel[]>([]), createOpen = ref(false), detailOpen = ref(false), detailLoading = ref(false), selected = ref<PcTaskDetail>(), approvalOpen = ref(false), approvalId = ref(''), recoveryDecision = ref(''), recoveryEvidence = ref(''), recoveryFingerprint = ref('')
const filter = reactive({ pageNum:1, pageSize:20, status:'', requester:'', search:'' }), form = reactive({ title:'', text:'', runnerId:'', modelId:'', mode:'REACT' as PcMode })
const states = ['ENQUEUED','LEASED','RUNNING','WAITING_APPROVAL','CANCELLING','CANCELLED','FAILED','COMPLETED','RECONCILE_REQUIRED','PAUSED_IMPORTED'], recoveryLabels: Record<string,string> = { CONFIRM_COMPLETED:'核实已完成', CONFIRM_FAILED:'核实失败', CONFIRM_CANCELLED:'核实已取消' }
let listGeneration = 0, detailGeneration = 0, detailController: AbortController | undefined
async function loadTasks() { const generation = ++listGeneration, id = workspaceId.value; if (!id || !checkPermi(['paicli:task:read'])) { tasks.value = []; total.value=0; return }; loading.value = true; pageError.value = ''; try { const response = await listTasks({ ...filter, workspaceId:id }); if (generation === listGeneration && id === workspaceId.value) { tasks.value = response.rows; total.value = response.total } } catch(cause) { if (generation === listGeneration) pageError.value = errorText(cause) } finally { if (generation === listGeneration) loading.value = false } }
function query() { filter.pageNum = 1; void loadTasks() }
async function showTask(id: string) { if(!checkPermi(['paicli:task:read']))return; const generation = ++detailGeneration; detailController?.abort(); detailController = new AbortController(); detailOpen.value = true; detailLoading.value = true; try { const response = await getTask(id, detailController.signal); if (generation === detailGeneration) { selected.value = response.data; recoveryDecision.value = ''; recoveryEvidence.value = ''; recoveryFingerprint.value = response.data.recovery?.currentFingerprint ?? '' } } catch(cause) { if (generation === detailGeneration && !detailController.signal.aborted) pageError.value = errorText(cause) } finally { if (generation === detailGeneration) detailLoading.value = false } }
async function create() { const data = { ...form, workspaceId:workspaceId.value }; await run(async () => { const response = await createTask(data, keys.get(data)); keys.done(data); createOpen.value = false; form.title = ''; form.text = ''; await loadTasks(); await showTask(response.data.id) }) }
async function cancel(task: PcTask) { if (task.importBatchId || !canCancel(task.status)) return; try { await ElMessageBox.confirm('取消会停止后续执行，已发生的副作用仍保留并需核对。确认提交？', '取消任务', { type:'warning', confirmButtonText:'提交取消', cancelButtonText:'返回' }) } catch { return }; const intent = { action:'cancel', id:task.id, version:task.version }; await run(async () => { await cancelTask(task.id, task.version, keys.get(intent)); keys.done(intent); ElMessage.info('已申请取消，正在等待最终回执。'); await loadTasks(); if (selected.value?.id === task.id) await showTask(task.id) }) }
async function reconcile() { const task = selected.value; if (!task?.recovery || !task.recovery.allowedDecisions.includes(recoveryDecision.value) || !/^[a-f0-9]{64}$/i.test(recoveryFingerprint.value)) return; const data = { decision:recoveryDecision.value, evidence:recoveryEvidence.value, currentFingerprint:recoveryFingerprint.value.toLowerCase() }, intent = { id:task.id, version:task.version, ...data }; await run(async () => { await reconcileTask(task.id, task.version, data, keys.get(intent)); keys.done(intent); await showTask(task.id); await loadTasks() }) }
function openApproval(id: string) { approvalId.value = id; approvalOpen.value = true }
async function download(id: string, name: string) { await run(async () => saveDownload(await downloadArtifact(id), name)) }
watch(workspaceId, async id => { detailGeneration++; detailController?.abort(); selected.value = undefined; detailOpen.value = false; filter.pageNum = 1; form.runnerId = ''; await loadTasks(); if (!id) return; try { const [rs,ms] = await Promise.all([checkPermi(['paicli:runner:list'])?listRunners(id):Promise.resolve({data:[]}),checkPermi(['paicli:connection:read'])?listModels(id):Promise.resolve({data:[]})]); if (id === workspaceId.value) { runners.value = rs.data; models.value = ms.data } } catch(cause) { pageError.value = errorText(cause) } })
onMounted(async()=>{ await loadWorkspaces(); if(typeof route.query.taskId === 'string') await showTask(route.query.taskId) }); onBeforeUnmount(() => { listGeneration++; detailGeneration++; detailController?.abort() })
</script>

